from pydantic import BaseModel
class OrderInput(BaseModel):
    quantity: int
    note: str = ""
constructed = OrderInput(quantity="3")
validated = OrderInput.model_validate({"quantity":"3"})

def inspect_input(quantity):
    first = OrderInput(quantity=quantity)
    second = OrderInput.model_validate({'quantity':quantity})
    return {'first':[first.quantity,first.note,type(first.quantity).__name__],'second':[second.quantity,second.note,type(second.quantity).__name__],'quantity_is_int':OrderInput.model_fields['quantity'].annotation is int,'note_is_str':OrderInput.model_fields['note'].annotation is str,'quantity_required':OrderInput.model_fields['quantity'].is_required(),'note_default':OrderInput.model_fields['note'].default,'constructed':[constructed.quantity,constructed.note],'validated':[validated.quantity,validated.note]}
